defmodule AshPhoenixStarter.Farms.FarmCrop do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farm_crops"
  end

  multitenancy do
    strategy :context
  end

  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  attributes do
    # Primary Key generated by Postgres via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :name, :string do
      allow_nil? false
      public? true
    end

    attribute :type, :string do
      allow_nil? false
      public? true
    end

    attribute :planting_season, :string do
      allow_nil? false
      public? true
    end

    attribute :growth_duration, :integer do
      allow_nil? false
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  actions do
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [:name, :type, :planting_season, :growth_duration]
    end

    update :update do
      primary? true
      accept [:name, :type, :planting_season, :growth_duration]
    end
  end
end
